package org.humanjourney.core.npc.economy;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;
class DiversitySafetyTest {
 BarterSolver.Good good(String id,long value,int stack){return new BarterSolver.Good(id,value,stack);}
 List<BarterSolver.Candidate> pool(){return BarterSolver.candidates(good("out",100,1),List.of(good("a_exact",100,1),good("b_exact",40,1),good("c_exact",60,1),good("d_near",95,1),good("e_near",30,1),good("f_near",65,1)));}
 BarterSolver.Candidate group(List<BarterSolver.Candidate> pool,String... ids){return pool.stream().filter(c->c.commodities().equals(List.of(ids))).findFirst().orElseThrow();}
 Random choose(int index){return new Random(0){@Override public int nextInt(int bound){return Math.floorMod(index,bound);}};}
 @Test void allFourCategoriesRemainEligibleWithoutGlobalPriority(){var p=pool();assertEquals(1,group(p,"a_exact").recipe().priority());assertEquals(2,group(p,"b_exact","c_exact").recipe().priority());assertEquals(3,group(p,"d_near").recipe().priority());assertEquals(4,group(p,"e_near","f_near").recipe().priority());for(int i=0;i<p.size();i++)assertEquals(p.get(i),PaymentDiversity.select(p,Map.of(),choose(i)));}
 @Test void commoditySetsAreUnorderedUniqueAndNotQuantityWeighted(){var p=BarterSolver.candidates(good("out",5,64),List.of(good("a",2,64),good("b",2,64)));assertEquals(3,p.size());assertEquals(3,p.stream().map(BarterSolver.Candidate::commodities).distinct().count());var reverse=BarterSolver.candidates(good("out",5,64),List.of(good("b",2,64),good("a",2,64)));assertEquals(p,reverse);var bound=new AtomicInteger();PaymentDiversity.select(p,Map.of(),new Random(0){public int nextInt(int b){bound.set(b);return 0;}});assertEquals(3,bound.get());}
 @Test void sameGoodTwoSlotRecipeSharesSingletonGroup(){var p=BarterSolver.candidates(good("out",100,1),List.of(good("a",1,64)));assertEquals(1,p.size());var r=p.getFirst().recipe();assertEquals(List.of("a"),p.getFirst().commodities());assertEquals(64,r.first().count());assertEquals(36,r.second().count());var usage=new HashMap<String,Integer>();PaymentDiversity.record(p.getFirst(),usage);assertEquals(1,usage.get("a"));}
 @Test void toleranceIsStrictAtBothBoundaries(){for(long value:new long[]{90,110})assertFalse(BarterSolver.candidates(good("out",100,1),List.of(good("a",value,1))).isEmpty());for(long value:new long[]{89,111})assertTrue(BarterSolver.candidates(good("out",100,1),List.of(good("a",value,1))).isEmpty());}
 @Test void everyMaterializedRecipeRespectsValuesAndStacks(){var p=BarterSolver.candidates(good("out",13,3),List.of(good("tool",8,1),good("stack",3,64),good("other",7,16)));for(var c:p){var r=c.recipe();assertTrue(r.error()*10<=r.outputValue());assertTrue(r.outputCount()>=1&&r.outputCount()<=3);assertTrue(r.first().count()<=r.first().good().stack());if(r.second()!=null)assertTrue(r.second().count()<=r.second().good().stack());}}
 @Test void nonStackablesStillCannotPayThreeTools(){assertTrue(BarterSolver.candidates(good("out",24,1),List.of(good("tool",8,1))).isEmpty());var p=BarterSolver.candidates(good("out",16,1),List.of(good("tool",8,1)));assertEquals(1,p.size());assertEquals(1,p.getFirst().recipe().first().count());assertEquals(1,p.getFirst().recipe().second().count());}
 @Test void unusedCombinationsWinEvenAgainstRepeatedExact(){var p=pool();var usage=new HashMap<String,Integer>();usage.put("a_exact",1);usage.put("b_exact",1);usage.put("c_exact",1);for(int i=0;i<p.size();i++){var chosen=PaymentDiversity.select(p,usage,choose(i));assertEquals(0,PaymentDiversity.usage(chosen,usage));assertFalse(chosen.commodities().contains("a_exact"));}}
 @Test void repeatedUseFallsBackToMinimumSummedDistinctUsage(){var p=pool();var usage=new HashMap<String,Integer>();for(var c:p)for(String id:c.commodities())usage.put(id,5);usage.put("d_near",1);assertEquals(List.of("d_near"),PaymentDiversity.select(p,usage,choose(0)).commodities());usage.put("d_near",5);usage.put("e_near",1);usage.put("f_near",1);assertEquals(List.of("e_near","f_near"),PaymentDiversity.select(p,usage,choose(0)).commodities());}
 @Test void sequentialNpcUsageAvoidsUnnecessaryRepeatsAndEventuallyAllowsThem(){var p=BarterSolver.candidates(good("out",10,1),List.of(good("a",10,1),good("b",10,1),good("c",10,1)));var usage=new HashMap<String,Integer>();for(int i=0;i<3;i++){var selected=PaymentDiversity.select(p,usage,choose(0));assertEquals(0,PaymentDiversity.usage(selected,usage));PaymentDiversity.record(selected,usage);}assertEquals(Map.of("a",1,"b",1,"c",1),usage);var next=PaymentDiversity.select(p,usage,choose(0));assertEquals(1,PaymentDiversity.usage(next,usage));}
 @Test void injectableRngAllowsDifferentEquivalentNpcPayments(){var p=pool();assertNotEquals(PaymentDiversity.select(p,Map.of(),choose(0)).commodities(),PaymentDiversity.select(p,Map.of(),choose(p.size()-1)).commodities());assertEquals(PaymentDiversity.select(p,Map.of(),new Random(123)),PaymentDiversity.select(p,Map.of(),new Random(123)));}
 @Test void selectedRecipePrefersValueQualityWithinItsGroup(){var c=group(BarterSolver.candidates(good("out",5,64),List.of(good("a",2,64))),"a");assertEquals(0,c.recipe().error());assertEquals(5,c.recipe().first().count());assertEquals(2,c.recipe().outputCount());}
 @Test void actualGeneratorTracksPerNpcUsageAndCrossNpcVariationWithoutChangingSellers()throws Exception{
  var fixture=new EconomyTest();var data=fixture.data();var role="human_journey:test_trader";var goods=new TreeMap<String,EconomyCatalog.Commodity>();
  for(String id:List.of("a","b","c"))goods.put("test:"+id,new EconomyCatalog.Commodity("test:"+id,"era_test",10_000_000L,"synthetic",7,List.of(),List.of(role),"minecraft:stone",null,fixture.any(),new com.google.gson.JsonObject()));
  for(int i=0;i<3;i++)goods.put("test:out"+i,new EconomyCatalog.Commodity("test:out"+i,"era_test",10_000_000L,"synthetic",7,List.of(role),List.of(),"minecraft:flint",null,fixture.any(),new com.google.gson.JsonObject()));
  var catalog=new EconomyCatalog(goods,Map.of());var settings=data.archetypes().get(role).economy(fixture.context());var one=EconomyGenerator.generate(catalog,role,fixture.context(),fixture.profile(),settings,fixture.items,choose(0));var two=EconomyGenerator.generate(catalog,role,fixture.context(),fixture.profile(),settings,fixture.items,choose(-1));
  assertEquals(Map.of("test:a",1,"test:b",1,"test:c",1),one.buyerUsage());assertTrue(one.offers().stream().allMatch(o->o.priorUsage()==0));assertEquals(one.offers().stream().map(o->o.output().id()).toList(),two.offers().stream().map(o->o.output().id()).toList());assertNotEquals(one.offers().stream().map(EconomyGenerator.Offer::paymentCommodities).toList(),two.offers().stream().map(EconomyGenerator.Offer::paymentCommodities).toList());
 }
 @Test void nearestQuantityOptimizationRetainsEveryBruteForceLegalGroup(){
  for(int av=1;av<=8;av++)for(int bv=1;bv<=8;bv++){
   var a=good("a",av,3);var b=good("b",bv,3);var output=good("out",7,4);var candidates=BarterSolver.candidates(output,List.of(a,b));long expected=Long.MAX_VALUE;
   for(int out=1;out<=4;out++)for(int qa=1;qa<=3;qa++)for(int qb=1;qb<=3;qb++){long error=Math.abs(av*qa+bv*qb-7L*out);if(error*10<=7L*out)expected=Math.min(expected,error);}
   var pair=candidates.stream().filter(c->c.commodities().equals(List.of("a","b"))).findFirst();if(expected==Long.MAX_VALUE)assertTrue(pair.isEmpty());else{assertTrue(pair.isPresent());assertEquals(expected,pair.orElseThrow().recipe().error());}
  }
 }
 WanderSafety.Point point(int x,int y,int z){return new WanderSafety.Point(x,y,z);}
 @Test void targetSafetyRejectsFluidsUnsupportedBlockedAndHazardous(){assertTrue(WanderSafety.land(false,true,true,true));assertFalse(WanderSafety.land(true,true,true,true));assertFalse(WanderSafety.land(false,false,true,true));assertFalse(WanderSafety.land(false,true,false,true));assertFalse(WanderSafety.land(false,true,true,false));assertFalse(SafeLandWandering.safeType(net.minecraft.world.level.pathfinder.PathType.WATER));assertFalse(SafeLandWandering.safeType(net.minecraft.world.level.pathfinder.PathType.LAVA));}
 @Test void flatAndOneBlockStepsAcceptedButLargerDropsAndJumpsRejected(){var from=point(0,64,0);assertTrue(WanderSafety.transition(from,point(1,64,0)));assertTrue(WanderSafety.transition(from,point(1,65,0)));assertTrue(WanderSafety.transition(from,point(1,63,0)));assertFalse(WanderSafety.transition(from,point(1,62,0)));assertFalse(WanderSafety.transition(from,point(1,66,0)));}
 @Test void safeTargetCannotHideFluidOrCliffAlongPath(){var start=point(0,64,0);var mid=point(1,64,0);var end=point(2,64,0);assertTrue(WanderSafety.route(start,List.of(start,mid,end),p->true));assertFalse(WanderSafety.route(start,List.of(start,mid,end),p->!p.equals(mid)));assertFalse(WanderSafety.route(start,List.of(start,point(1,62,0),point(2,62,0)),p->true));}
 @Test void diagonalAndNativeCornerCutGuardsRejectUnsafeFlanks(){var start=point(0,64,0);var wet=point(0,64,1);var end=point(1,64,1);assertFalse(WanderSafety.route(start,List.of(start,end),p->!p.equals(wet)));assertFalse(WanderSafety.route(start,List.of(start,point(1,64,0),end),p->!p.equals(wet)));assertTrue(WanderSafety.route(start,List.of(start,end),p->true));}
 @Test void allUnsafeAttemptsStayPutAndSearchIsBounded(){var attempts=new AtomicInteger();var result=WanderSafety.firstSafe(i->{attempts.incrementAndGet();return i;},i->false);assertTrue(result.isEmpty());assertEquals(16,attempts.get());assertEquals(3,WanderSafety.firstSafe(i->i,i->i==3).orElseThrow());}
 @Test void recoveryIsIndependentOfStrictVoluntarySafety(){assertTrue(WanderSafety.recovery(false,true,64,64));assertTrue(WanderSafety.recovery(true,false,64,64));assertTrue(WanderSafety.recovery(true,true,62,64));assertFalse(WanderSafety.recovery(true,true,63,64));assertFalse(WanderSafety.recovery(true,true,64,64));}
 ClassNode read(String name)throws Exception{try(var in=getClass().getClassLoader().getResourceAsStream(name+".class")){assertNotNull(in);var c=new ClassNode();new ClassReader(in).accept(c,0);return c;}}
 @Test void actualMovementCallsSafetyAndKeepsSeparateRecoveryPath()throws Exception{var c=read("org/humanjourney/core/npc/economy/EconomyMovement$HomeGoal");var calls=new ArrayList<String>();for(var m:c.methods)for(var i:m.instructions)if(i instanceof MethodInsnNode call)calls.add(call.name);assertTrue(calls.containsAll(List.of("recovery","landAt","path","firstSafe","createPath")));}
 @Test void familyPersistenceAndNonNpcIntegrationRemainOnExistingCodePaths()throws Exception{var c=read("org/humanjourney/core/npc/economy/EconomySpawn");assertTrue(c.methods.stream().anyMatch(m->m.name.equals("nativeOffers")));var generator=read("org/humanjourney/core/npc/economy/EconomyGenerator");var calls=new ArrayList<String>();for(var m:generator.methods)for(var i:m.instructions)if(i instanceof MethodInsnNode call)calls.add(call.name);assertTrue(calls.contains("candidates"));assertFalse(calls.contains("solve"));}
}
